/// The unit's pump efficiency, uniform between lo and hi, drawn from disp.
/// - lo: real[1] (passed a plain number)
/// - hi: real[1] (passed a plain number)
/// - disp: inout stream (passed a random stream, as six numbers)
/// - returns eta: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn pump_efficiency(lo: f64, hi: f64, disp: &mut rt::Stream) -> f64 {
    let mut eta: f64 = 0.0;
    let mut u: f64 = rt::uniform(&mut (*disp));
    eta = (lo + ((hi - lo) * u));
    eta
}

/// The pump's power [W] at torque pump [N m], the ring's momentum h [N m s] and its constants: momentum per flow speed
/// k_hv [N m s/(m/s)], channel length l [m], enclosed area s [m^2], bore area ac [m^2], efficiency eta.
